                state: { "立场": "奥古斯丁（应对一）", "恶的来源": "本性的秩序被破坏", "恶的实在性": "有因果效力的缺失", "承重前提": "受造本性有一个应当的秩序", "未解的问题": "规范性的秩序如何能被证明而不只是被设定" },
