          author: "奥古斯丁（Aurelius Augustinus）",
          work: "《忏悔录》（Confessiones）第十一卷第十四章、第二十章、第二十六章至第二十八章（卷次章节依通行拉丁文本，中译参照商务印书馆汉译本）",
          passage: "（以下是《忏悔录》第十一卷关于时间的几段核心论述的忠实概述，非逐字引文；括注中的拉丁文短语是原文术语，个别短语在抄本与校勘本间有异文。）我向你承认，我至今仍不知道时间究竟是什么。可是我承认这一点：如果没有过去的事物，就没有过去的时间；如果没有将来的事物，就没有将来的时间；如果没有现在的事物，也就没有现在的时间。那么，这两种时间（过去与将来）如何存在呢？如果说过去与将来都存在，它们又在哪里？过去已经不在，将来还没有来。至于现在，如果它永远是现在而不流逝，它就不是时间而成了永恒。可见时间之所以是时间，正因为它趋向不存在。这样一来，我们凭什么说「一段长的时间」或「一段短的时间」？长与短只能对已经存在的东西说。可是过去已不存在，将来尚未存在，谁也无法测量不在的东西。于是我转向另一种想法：时间分过去、现在、将来三类，并不妥当，更准确的说法也许是三类现在——过去之物的现在、现在之物的现在、将来之物的现在。这三类现在在我心里各有其位置：过去之物的现在是记忆（memoria），现在之物的现在是注意（contuitus），将来之物的现在是期待（expectatio）。我还注意到一件事：我曾听人说过，时间是天体的运动，但我不同意。因为一个天体的运行本身也是在一段时间里完成的；即使天体停住而陶轮继续转动，我们仍会用那转动来计时间。因此我倾向于这样一个规定：时间是一种心灵的延展（distentio animi）。可是我仍然承认，我看不透时间的秘密，只能在你那里找到安息。",
          note: "本段为依据《忏悔录》第十一卷整理的中文概述，不是逐字引文；括注中的拉丁文短语（memoria、contuitus、expectatio、distentio animi）是原文术语，其中第三项在部分抄本与译本中写作 attenti，此处取其「注意」这一读法。选这一段的目的不是让读者接受某个时间理论，而是看一个哲学家如何处理「我每天都在用、却说不清它是什么」的东西：他先用否定的方式逼近（过去不在、将来不在），再用类比分层（三类现在），最后给出一个规定（心灵的延展），并且没有掩饰自己仍然不满意。读法提示：不要把 distentio animi 读成「时间是我的主观错觉」——奥古斯丁同时保留了时间的客观起点（万物被造）、时间的度量（心灵的印象）与永恒（上帝的「永远的现在」）三者，如何把三者放进一个体系，是他的难题，也是后世从胡塞尔到海德格尔反复回到这一段的原因。",
          annotations: [
            { line: "我向你承认，我至今仍不知道时间究竟是什么。", note: "全书最有名的一句话的忠实概述（「时间究竟是什么？没有人问我，我倒清楚；有人问我，我想说明，便茫然不解了」这类措辞出自中译通行译本，拉丁文异文较多）。这个姿态不是修辞：它是一次方法示范，把「用得很熟」与「说得清楚」明确分开。练习写作时可以直接套用这个结构：先承认自己也在使用某物，再暴露自己说不清它。" },
            { line: "如果它永远是现在而不流逝，它就不是时间而成了永恒。", note: "这一句是通向「永恒」（aeternitas）的桥。奥古斯丁的上帝不在时间里，而是「永远的现在」；因此「上帝在创造世界之前在做什么」这个问题本身预设了上帝在时间里，属于问题被问错，而不是答案被藏起来。" },
            { line: "长与短只能对已经存在的东西说。", note: "时间度量的悖论在这里被压缩成一行：过去不在、将来不在，所以严格说没有「长的时间」可量。奥古斯丁的出口在下一句（度量的是心灵中的印象），而不是承认时间不存在。这里也是与分析哲学对话的入口——现代讨论把这类困难整理成「时间之矢与度量」的问题。" },
            { line: "过去之物的现在是记忆（memoria），现在之物的现在是注意（contuitus），将来之物的现在是期待（expectatio）。", note: "三个拉丁词要背下来，它们是奥古斯丁时间分析的骨架：过去以记忆的方式在，将来以期待的方式在，现在以注意的方式在。关键在于「在」的方式被改写了：不再问某段时间是否存在，而问它以什么方式存在于心灵中。" },
            { line: "时间是一种心灵的延展（distentio animi）。", note: "这是本段的结论，意思是心灵把过去、现在、将来伸展成一个统一的可度量结构。它有两个方向被后世继承：现象学把「延展」发展成意识的时间性（胡塞尔的滞留与预持），而物理学方向则完全不接受心灵依赖说——相对论之后的时间度量与观察者状态相关，却与记忆无关。写给论文时要把这层区别点出来。" },
            { line: "我曾听人说过，时间是天体的运动，但我不同意。", note: "这是对当时流行的「时间是天的运动」这一规定的反驳，用的是反例法：天体停下、陶轮还在转，我们仍会量时间，所以时间不等于天体运动。看这个反例的结构——它只需要一个可设想的分离情形，不需要任何天文观测，这是哲学里用思想实验反驳定义的范例。" }
          ],
          questions: [
            "把本段出现的所有主张列出来，分成三类：哪些是关于时间本身的事实主张，哪些是关于我们如何谈论时间的语言分析，哪些是关于心灵状态的主张？",
            "「度量的是心灵中的印象」这一回答能解决「过去已不在、为何还能被量」的困难吗？如果不能，它缺的是哪一步？",
            "如果你坚持时间是客观的、与心灵无关，你会怎样回应「陶轮」那个反例？请把回应写成两条前提加一条结论。"
          ]
