        {
          type: "concept",
          title: "原罪与政治：《上帝之城》里两种爱构成的两座城",
          md: "《上帝之城》（De civitate Dei，写于 413 至 426 年间，共二十二卷）的写作动机是一次具体的公共危机：410 年西哥特人攻陷罗马，异教残余势力说这是因为罗马抛弃了旧神、改信了基督教。奥古斯丁用二十二卷回答这个问题，其中第十四卷给出两座城的定义，第十九卷讨论正义与和平。两座城的分界不是机构而是爱：地上之城（civitas terrena）由「爱自己以至轻视上帝」的爱所构成，上帝之城（civitas Dei）由「爱上帝以至轻视自己」的爱所构成。注意这个定义的构造方式——它是一个关于「什么把人群绑在一起」的判断：使一群人成为一个城的，是共同所爱的东西，而不是共同的疆界、血统或制度。这样理解就能解释两个容易读错的地方。其一，两座城在现世历史中交织（奥古斯丁用的比喻是同一块田里的麦子与稗子一起长到收割），因此不存在一份可以核对的成员名单；其二，判断标准是爱的次序而非身份标签，所以名义上的基督徒也可能按地上之城的方式生活。原罪（peccatum originale）在这里承担了结构性的工作：亚当的堕落使人失去了原本可以不犯罪的完整状态，人的欲望不再自然服从理性，因此任何人间制度都不可能靠自身达成完全的正义，政治的作用是在堕落后的人性条件下提供有限的秩序与和平。这一判断给了奥古斯丁一条很有力也很尖刻的论证：没有正义的共同体，与一伙强盗有什么区别（大意如此，此处为对其论述的概述，非逐字引文）；他接着反问，强盗团伙本身不也是一个有首领、有协议、有分赃规则的小王国吗？这一步的意思是：正义如果只是强者的利益，那么王国与匪帮的差别只在规模。在《上帝之城》第十九卷里，他进一步说，即使最正义的共同体，其和平也只是相对的、暂时的，真正的和平（pax）只在上帝之城里完满。这条路线对后世的影响是双向的：一方面它是西方政治思想中「政治权威的正当性有内在限度」这一观念的来源之一（政府的功能是维持秩序，而不是使人得救）；另一方面它也常被批评为把政治的改善空间压得太低——如果人性在结构上已经损坏，制度改革的意义在哪里？中世纪的政教之争、近代的正义战争理论、乃至现代现实主义国际关系理论都在不同程度上继承了这一张力。这里要补一句常被跳过的中立事实：奥古斯丁对异端的处理与帝国对多纳图派（Donatists）的镇压，是他一生中争议最大的部分；他早期主张劝说，后期接受了帝国强制手段（可参见他写给多纳图派的书信与相关诏令的记载）。把这一点写进课程不是因为它是脚注，而是因为它示范了一件事：一个论证「恶是缺乏、意志是恶的作者」的人，在现实制度压力下也会为强制辩护——哲学立场与政治行为之间的距离，是读思想史时必须一起看的两样东西。"
        }
