          gap: "形式上的缺口在第三步到结论之间：前提只说明了「纯恶不能作为独立本原起作用」，结论却断言「一切恶都是缺失」。要补的是一座桥——「恶要么是实体要么是缺失，而既然不能是实体，就只能是缺失」，这条析取前提没有人写出来，但它承担了全部工作；若存在第三种情况（例如恶是关系、是结构、是意志的行动类型而不宜归入缺失），桥梁就断。内容上最弱的前提是 P2：「起作用即是一种成全」把「有力」直接等同于「好」。什么会推翻它：给出一个其力量无可称善的能力——例如纯粹的破坏力、或一个只在毁灭中显现的能力。若 P2 倒下，整个转向就得改走别的路（例如把恶规定为意志的错误行动而不谈缺失）。第三条可疑处是 P1 的「存在即善」，它是一个价值与存在的等同断言，需要创造论支撑，对不接受创造论的读者等于零。" 
