        {
          type: "concept",
          title: "法、自然法与政治：本性与恩典的分工在制度上的后果",
          md: "《神学大全》第二集第一部第 90 至 108 题通常被称为「法论」（tractatus de legibus），它是中世纪政治哲学最系统的文本之一。四种法的结构在第 91 题：永恒法（lex aeterna）是上帝对万物的治理理念；自然法（lex naturalis）是理性受造物对永恒法的分有（此处为对第 91 题第 2 条主张的概述），它的第一条诫命是「应当行善、追求善、避免恶」，其余具体条目由实践理性逐步推出；人法（lex humana）是从自然法推导出来的具体制度规定，用于维持公共秩序；神法（lex divina）是启示给出的法，用于指引人达到超出自然理性的终极目的。这个结构要抓住三个要点。第一，自然法不是一份详细的行为清单，而是一套由实践理性推导的框架：阿奎那明确说，越往下推导，结论越具体、也越容易出错（他在第 94 题里讨论过不同民族对具体条目的分歧），因此自然法的第一原理稳定，具体的适用有讨论空间。第二，人法的效力有内在限度：与自然法冲突的人法「在良心面前不再是法」（此处为对第 95 至 96 题相关论述的意译概述），这一条为后世抵抗不义法律提供了理论依据，尽管阿奎那本人同时强调为了避免混乱，有些恶法仍可被容忍。第三，政治的位置。阿奎那继承亚里士多德「人是政治的动物」这一判断，认为政治生活是本性的一部分而不是堕落的惩罚，因此国家有正面的自然目的（提供公共善与秩序），不必像奥古斯丁那样只把政治理解为对堕落后人性的补救。差别要讲得准确：奥古斯丁并不否认政治的必要与相对正当，他只是不认为现世政治能达成真正的正义；阿奎那也不认为世俗国家能使人得救，他只是把自然目的与超自然目的分成两层，各归其位。这一分工在制度史上有一个直接的继承者：16 至 17 世纪的国际法与正义战争理论（维多利亚、苏亚雷斯、格劳秀斯）大量使用自然法框架，把「即使不诉诸启示也能确定的权利与义务」当作跨政治体交往的基础，这条线索一直通到近代自然权利学说。要抵住的误读是把自然法读成「从事实直接推出应当」：阿奎那的推导起点不是观察到的自然规律，而是实践理性的第一条原理（应当追求善），它本身不是从事实推出的，而是被看作实践理性的自明起点。至于这条起点是否真的自明，休谟在《人性论》第三卷提出的「是／应当」问题正是冲它来的——本站《伦理学》第 1 讲与《近代哲学》相关讲次会接着讨论。"
        }
