          front: "共相（universale）指的是什么？为什么它不是「概念」的同义词？",
          back: "共相指「能被许多个别事物共同拥有或共同述说」的东西，例如「人」「动物」「白」。它为什么存在、以什么方式存在正是争论的焦点：实在论说它是独立实在或事物中的共同本质，概念论与唯名论说它只是心灵中的概念或名称。把共相直接等同于概念，等于先站到了某一派上。",
