                state: { "环节": "5. 新的限度", "内容": "相互承认在历史中的不完备形态", "这一环的自我要求": "承认的普遍性", "暴露的矛盾": "承认的范围总被实际的社会形态所限制", "扬弃了什么": "每一次不完备形态都被取消并保存" },
                note: "这一步是理解「历史有目的」的入口：推进不是任意换题，而是每一种形态在兑现自己的要求时暴露限度。下一步要把这个结构从个人意识史扩到世界史。"
